mapper.select:
SELECT d.id AS device_id, d.device_no, d.device_name, d.device_type, d.status AS device_status, m.id AS meter_id, m.meter_no, m.meter_name, m.meter_type, m.display_type, m.unit, m.status AS meter_status, dm.created_by, dm.created_at AS bound_at FROM device_meter AS dm INNER JOIN device AS d ON d.id = dm.device_id AND d.deleted = 0 INNER JOIN meter AS m ON m.id = dm.meter_id AND m.deleted = 0 WHERE 1 = 1
AND dm.device_id = #{deviceId}
AND dm.meter_id = #{meterId}
AND (d.device_no LIKE CONCAT('%', #{keyword}, '%') OR d.device_name LIKE CONCAT('%', #{keyword}, '%') OR m.meter_no LIKE CONCAT('%', #{keyword}, '%') OR m.meter_name LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY dm.created_at DESC, dm.device_id DESC, dm.meter_id DESC

SELECT m.id AS meter_id, m.meter_no, m.meter_name, m.meter_type, m.display_type, m.unit, m.status, m.version, dm.created_at AS bound_at FROM device_meter AS dm INNER JOIN meter AS m ON m.id = dm.meter_id AND m.deleted = 0 WHERE dm.device_id = #{deviceId}
AND (m.meter_no LIKE CONCAT('%', #{keyword}, '%') OR m.meter_name LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY dm.created_at DESC, dm.meter_id DESC

SELECT d.id AS device_id, d.device_no, d.device_name, d.device_type, d.status, d.version, dm.created_at AS bound_at FROM device_meter AS dm INNER JOIN device AS d ON d.id = dm.device_id AND d.deleted = 0 WHERE dm.meter_id = #{meterId}
AND (d.device_no LIKE CONCAT('%', #{keyword}, '%') OR d.device_name LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY dm.created_at DESC, dm.device_id DESC
